UITrophyExplosionEmitter=function(game){Phaser.Particles.Arcade.Emitter.call(this,game,0,0,80);this.particleClass=UITrophyExplosionParticle;this.makeParticles('celebration',['explosion0','explosion1','explosion2']);this.minParticleSpeed.setTo(UIConstants.TROPHY_EXPLOSION_MIN_X_SPEED,UIConstants.TROPHY_EXPLOSION_MIN_Y_SPEED);this.maxParticleSpeed.setTo(UIConstants.TROPHY_EXPLOSION_MAX_X_SPEED,UIConstants.TROPHY_EXPLOSION_MAX_Y_SPEED);this.particleDrag.setTo(UIConstants.TROPHY_EXPLOSION_DRAG_X,UIConstants.TROPHY_EXPLOSION_DRAG_Y);this.setAlpha(0.8,1.0);this.setRotation(-60,60);this.minParticleScale=0.7;this.maxParticleScale=1.0;this.gravity=0;this.kill();this.visible=false;};UITrophyExplosionEmitter.prototype=Object.create(Phaser.Particles.Arcade.Emitter.prototype);UITrophyExplosionEmitter.prototype.constructor=UITrophyExplosionEmitter;UITrophyExplosionEmitter.prototype.update=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.update.call(this);if(this.countLiving()==0){this.kill();this.visible=false;}};UITrophyExplosionEmitter.prototype.postUpdate=function(){if(!this.exists){return;}Phaser.Particles.Arcade.Emitter.prototype.postUpdate.call(this);};UITrophyExplosionEmitter.prototype.spawn=function(x,y){this.revive();this.visible=true;this.x=x;this.y=y;this.explode(2500,80);};UITrophyExplosionEmitter.prototype.retire=function(){this.kill();this.visible=false;this.callAll('retire');};